using MediatR; using Microsoft.AspNetCore.Mvc; using PamirPlastik.Application.Features.Mediator.Queries.FairQueries; namespace PamirPlastik.WebApi.Controllers { [Route("api/[controller]")] [ApiController] public class FairsController : ControllerBase { private readonly IMediator _mediator; public FairsController(IMediator mediator) { _mediator = mediator; } [HttpGet] public async Task<IActionResult> FairList() { var values = await _mediator.Send(new GetFairQuery()); return Ok(values); } [HttpGet("{id}")] public async Task<IActionResult> GetFair(int id) { var value = await _mediator.Send(new GetFairByIdQuery(id)); return Ok(value); } } }
